let w = window_rect("AutoFlow Manual Acceptance Harness");
if w.found {
    let x1 = w.x + w.width * 45 / 100;
    let x2 = w.x + w.width * 55 / 100;
    let y = w.y + w.height * 50 / 100;
    let i = 0;
    while i < 12 {
        move_to(x1, y);
        wait_ms(250);
        move_to(x2, y);
        wait_ms(250);
        i += 1;
    }
}
